var nonLinearSlider=document.getElementById("nonlinear");noUiSlider.create(nonLinearSlider,{connect:!0,behaviour:"tap",start:[1,3e3],range:{min:[1],"10%":[5e3,5e3],"50%":[4e4,5e3],max:[75e3]}});var nodes=[document.getElementById("lower-value"),document.getElementById("upper-value")];nonLinearSlider.noUiSlider.on("update",function(e,n){e=Number(e[n]).toLocaleString("en-AE",{minimumFractionDigits:0});nodes[n].innerHTML=e});